const room = { id: rooms[0].id, name: 'Habitaciones', type: 'Habitaciones', number: rooms.map((item) => item.number || item.id).join(' + '), baseAdultsCapacity: rooms.reduce((sum, item) => sum + Number(item.baseAdultsCapacity || 0), 0), maxAdultsCapacity: rooms.reduce((sum, item) => sum + Number(item.maxAdultsCapacity || 0), 0), childrenCapacity: rooms.reduce((sum, item) => sum + Number(item.childrenCapacity || 0), 0), extraGuestPrice: extraPrices.length ? extraPrices.reduce((sum, value) => sum + value, 0) / extraPrices.length : 0, allowsPets: rooms.every((item) => item.allowsPets !== false), pricePerNight: totalNightly };
